function useRazorpay(){
  return async (booking,paymentMethod='razorpay')=>{
    const order=await createRazorpayOrder(booking.orderId)
    await new Promise((resolve,reject)=>{if(window.Razorpay)return resolve();const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=()=>reject(new Error('Razorpay checkout could not load.'));document.body.appendChild(s)})
    return new Promise((resolve,reject)=>{const u=currentUser()||{};const email=booking.customerEmail||u.email||'';const contact=booking.phone||u.phone||'';const prefill={name:booking.name||u.name||'',email,contact};if(paymentMethod==='upi'&&!email)delete prefill.email;const options={key:order.keyId,amount:order.amount,currency:order.currency,name:'Tiffin Wallah',description:`${booking.service} - ${booking.orderId}`,order_id:order.razorpayOrderId,prefill,notes:{payment_preference:paymentMethod},theme:{color:'#071a3a'},handler:async response=>{try{const verified=await verifyRazorpayPayment(booking.orderId,{...response,payment_preference:paymentMethod});resolve(verified.booking)}catch(e){reject(e)}}};if(paymentMethod==='upi'&&email&&contact)options.prefill.method='upi';const rzp=new window.Razorpay(options);rzp.on('payment.failed',r=>reject(new Error(r.error?.description||'Payment failed.')));rzp.open()})
  }
}
function CinematicPageHero({eyebrow,title,subtitle,image,children}){const videoSrc=eyebrow?.toUpperCase().includes('PARTY')?serviceVideos.party:eyebrow?.toUpperCase().includes('PRESS')||eyebrow?.toUpperCase().includes('LAUNDRY')?serviceVideos.laundry:serviceVideos.tiffin;return <section className="service-cinematic-hero video-service-hero"><VideoMedia src={videoSrc} className="service-hero-video" label={`${eyebrow} background video`}/><div className="service-hero-overlay"/><div className="service-hero-content"><div className="cinematic-meta"><span>{eyebrow}</span><span>TIFFIN WALLAH</span></div><div className="cinematic-line"/><h1>{title}</h1><p>{subtitle}</p>{children}</div></section>}

