    <div className="package-grid tiffin-plan-grid">{(menu.monthlyPlans||[]).map(x=><button type="button" key={x.id} className={plan===x.id?'package-card active':'package-card'} onClick={()=>setPlan(x.id)}><span>{x.name}</span><strong>₹{Number(x.price).toLocaleString('en-IN')}<small>/ month</small></strong><p>{x.description}</p></button>)}</div>
